1	export type QuoteResult = { premium: number };
2	
3	export type ScenarioResults = { results: QuoteResult[] };
4	
5	const PROCESSING_FEE = 5;
6	
7	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
8	
9	const ITEM_BASE_PREMIUM: Record<string, number> = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	};
16	
17	type Item = { type: string };
18	
19	type Step = { op: string; items: Item[] };
20	
21	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
22	
23	const BLOCK_SIZE = 3;
24	
25	// Forced so far only by a policy that is nothing but one rune block, so this is
26	// the premium of the whole policy, not yet of a block within a larger policy.
27	const THREE_RUNE_BLOCK_BASE_PREMIUM = 60;
28	
29	const isThreeRuneBlock = (items: Item[]): boolean =>
30	  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");
31	
32	const policyBasePremium = (items: Item[]): number => {
33	  if (isThreeRuneBlock(items)) return THREE_RUNE_BLOCK_BASE_PREMIUM;
34	
35	  return items.reduce((sum, item) => sum + ITEM_BASE_PREMIUM[item.type], 0);
36	};
37	
38	const quoteStep = (step: Step): QuoteResult => {
39	  const basePremium = policyBasePremium(step.items);
40	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
41	  return {
42	    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
43	  };
44	};
45	
46	export const runScenario = (scenario: Scenario): ScenarioResults => ({
47	  results: scenario.steps.map(quoteStep),
48	});
49

