const quoteStep = (step: Step): QuoteResult => {
  const basePremium = policyBasePremium(step.items);
  const afterPercentageModifiers =
    basePremium * (1 + FIRST_INSURANCE_SURCHARGE_RATE);

  // The fee is added after every percentage modifier, and only the final
  // premium is rounded — intermediates stay fractional.
  return { premium: Math.ceil(afterPercentageModifiers + PROCESSING_FEE) };
};

