// Deliberately additive, not `base * (1 + rate)`: the latter is the same in
// exact arithmetic but not in binary floating point (100 * 1.1 is
// 110.00000000000001), and Math.ceil turns that 1e-14 into a whole gold piece.
const afterPercentageModifiers =
  basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
